        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.domainState || {};
            var rep = ds.reputation || 0;
            var data = ds.dataIntegrity || 0;
            var sec = ds.securityLevel || 0;
            var comp = ds.compliance || 0;
            var totalSpent = ds.totalSpent || 0;
            var ransomPaid = ds.ransomPaid || false;

            var compositeScore = Math.round((rep * 0.25) + (data * 0.25) + (sec * 0.25) + (comp * 0.25));

            var performance = 'Needs Improvement';
            if (compositeScore >= 75) performance = 'Excellent Cyber Resilience';
            else if (compositeScore >= 60) performance = 'Strong Crisis Management';
            else if (compositeScore >= 45) performance = 'Adequate Response';

            var insights = [];
            if (ransomPaid) {
                insights.push('Paying the ransom reduced costs but introduced legal and ethical risks.');
            } else {
                insights.push('Not paying the ransom was the principled choice, though more expensive.');
            }
            if (sec >= 70) {
                insights.push('Strong post-crisis security investment will protect against future attacks.');
            } else {
                insights.push('Security investment may be insufficient to prevent future incidents.');
            }
            if (rep >= 70) {
                insights.push('Reputation was well managed through the crisis.');
            } else {
                insights.push('Reputation took significant damage during the crisis.');
            }
            if (data < 80) {
                insights.push('Data recovery was incomplete. Better backup policies would have prevented this.');
            }
            insights.push('Preventive cybersecurity investment ($500K) would have been 10x cheaper than this crisis ($' + Math.round(totalSpent / 1000) + 'K).');

            return {
                compositeScore: compositeScore,
                totalSpent: totalSpent,
                reputation: rep,
                dataIntegrity: data,
                securityLevel: sec,
                compliance: comp,
                ransomPaid: ransomPaid,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var period = state.currentPeriod;
            if (period === 1 && results.cost > 350000) return window.mySimulation.t('hint_r1_high_spend');
            if (period === 2 && state.domainState.ransomPaid) return window.mySimulation.t('hint_r2_paid');
            if (period === 2 && !state.domainState.ransomPaid) return window.mySimulation.t('hint_r2_rebuild');
            if (period === 3 && results.strategy === 3) return window.mySimulation.t('hint_r3_delayed');
            if (period === 3 && state.domainState.ransomPaid) return window.mySimulation.t('hint_r3_aml');
            if (period === 4 && results.secDelta < 30) return window.mySimulation.t('hint_r4_low_security');
            return null;
        }

